const releaseSessionInput = `-- name: ReleaseSessionInput :execrows
UPDATE session_input_queue
SET status = ?1, dispatch_started_at = NULL, updated_at = ?2
WHERE id = ?3 AND session_id = ?4
  AND status = ?5
`

type ReleaseSessionInputParams struct {
	QueuedStatus      string `json:"queued_status"`
	UpdatedAt         string `json:"updated_at"`
	ID                string `json:"id"`
	SessionID         string `json:"session_id"`
	DispatchingStatus string `json:"dispatching_status"`
}

func (q *Queries) ReleaseSessionInput(ctx context.Context, arg ReleaseSessionInputParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, releaseSessionInput,
		arg.QueuedStatus,
		arg.UpdatedAt,
		arg.ID,
		arg.SessionID,
		arg.DispatchingStatus,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
